#include <string.h>
#include "jpegcompressor.h"
#include "openjpeg.h"

/*
 * JPEG 2000 compressor based on OpenJPEG, without dynamic memory allocation.
 *
 * Usage:
 *   1. write_buffer: upload the raw image in chunks. A chunk must start at
 *      most at the end of the data already uploaded (no gaps), so chunks can
 *      be re-sent but not skipped. Call clear_buffer before a new image.
 *      Layout: planar (all samples of component 0, then component 1, ...),
 *      each component row by row; 1 byte per sample for bit-depth <= 8,
 *      otherwise 2 bytes per sample, little endian.
 *   2. start_compression: compress the uploaded image into a raw JPEG 2000
 *      codestream; compression_completed is sent when done.
 *   3. read_buffer: download the compressed data in chunks.
 *   status can be called at any time, clear_buffer forgets the uploaded and
 *   compressed data.
 *
 * Memory: three static buffers (pool, input, output). The image is fed to
 * OpenJPEG tile by tile (opj_write_tile), so the pool only needs to hold the
 * encoder working data of one tile, not of the whole image. The status
 * memory-peak field gives the pool usage of the last compression, to tune
 * JPEGCOMPRESSOR_MEM_POOL_SIZE.
 */

// Encoder memory pool, used by OpenJPEG for all its allocations
#ifndef JPEGCOMPRESSOR_MEM_POOL_SIZE
#define JPEGCOMPRESSOR_MEM_POOL_SIZE (4U * 1024U * 1024U)
#endif

// Raw image upload buffer, bounds the image size
#ifndef JPEGCOMPRESSOR_INPUT_BUFFER_SIZE
#define JPEGCOMPRESSOR_INPUT_BUFFER_SIZE (1024U * 1024U)
#endif

// Compressed data buffer
#ifndef JPEGCOMPRESSOR_OUTPUT_BUFFER_SIZE
#define JPEGCOMPRESSOR_OUTPUT_BUFFER_SIZE (1024U * 1024U)
#endif

// Size of the OpenJPEG stream internal buffer (allocated from the pool)
#ifndef JPEGCOMPRESSOR_STREAM_CHUNK_SIZE
#define JPEGCOMPRESSOR_STREAM_CHUNK_SIZE (4096U)
#endif

// Buffers are declared as 64-bit words to keep them aligned
#define JPEGCOMPRESSOR_WORDS(size) (((size) + 7U) / 8U)

static OPJ_UINT64 opj_pool_buffer[JPEGCOMPRESSOR_WORDS(JPEGCOMPRESSOR_MEM_POOL_SIZE)];
static OPJ_UINT64 input_words[JPEGCOMPRESSOR_WORDS(JPEGCOMPRESSOR_INPUT_BUFFER_SIZE)];
static OPJ_UINT64 output_words[JPEGCOMPRESSOR_WORDS(JPEGCOMPRESSOR_OUTPUT_BUFFER_SIZE)];

#define INPUT_BUFFER  ((OPJ_UINT8 *)input_words)
#define OUTPUT_BUFFER ((OPJ_UINT8 *)output_words)

// Encoder parameters, kept static as the structure is ~18 KB (too big for the stack)
static opj_cparameters_t encoder_parameters;

static struct {
   asn1SccJpeg_Compressor_State state;
   asn1SccJpeg_Result_Code last_result;
   OPJ_SIZE_T input_size;       // bytes uploaded contiguously from offset 0
   OPJ_SIZE_T output_size;      // compressed bytes available
   OPJ_BOOL output_overflow;    // the compressed data did not fit
   OPJ_SIZE_T memory_peak;      // encoder pool peak usage of the last compression
   OPJ_SIZE_T memory_leaked;    // pool bytes OpenJPEG had not freed at the end of the
                                // last compression (expected 0, released anyway)
   OPJ_SIZE_T memory_high_water; // highest pool offset used by the last compression:
                                 // memory_peak plus the memory lost to fragmentation
} compressor = { Jpeg_Compressor_State_idle, Jpeg_Result_Code_ok, 0U, 0U, OPJ_FALSE, 0U, 0U, 0U };

// Image geometry derived from the configuration
typedef struct {
   OPJ_UINT32 width;
   OPJ_UINT32 height;
   OPJ_UINT32 num_components;
   OPJ_UINT32 bytes_per_sample;
   OPJ_UINT32 tile_width;
   OPJ_UINT32 tile_height;
   OPJ_UINT32 tiles_x;
   OPJ_UINT32 tiles_y;
   OPJ_SIZE_T image_size;       // raw image size in bytes
} image_geometry_t;


// OpenJPEG output stream: a codestream is written sequentially (no seek)
static OPJ_SIZE_T stream_write(void *data, OPJ_SIZE_T size, void *user_data)
{
   (void)user_data;
   if (size > JPEGCOMPRESSOR_OUTPUT_BUFFER_SIZE - compressor.output_size) {
      compressor.output_overflow = OPJ_TRUE;
      return (OPJ_SIZE_T)-1;
   }
   memcpy(OUTPUT_BUFFER + compressor.output_size, data, size);
   compressor.output_size += size;
   return size;
}


/* ---------------------------------------------------------------------- */
/* Compression                                                             */
/* ---------------------------------------------------------------------- */

// Each wavelet decomposition level halves the tile size, and a tile coded
// with N resolutions goes through N - 1 levels: its width and height must be
// at least 2^(N - 1) pixels so that the lowest resolution keeps at least one
// pixel. OpenJPEG rejects smaller tiles in opj_start_compress
// (opj_j2k_encoding_validation), checking the nominal tile size like here,
// not the size of the partial edge tiles.
static OPJ_BOOL tile_supports_resolutions(const image_geometry_t *geometry, OPJ_UINT32 resolutions)
{
   const OPJ_UINT32 min_tile_size = (geometry->tile_width < geometry->tile_height) ?
                                    geometry->tile_width : geometry->tile_height;

   return (min_tile_size >= (1U << (resolutions - 1U))) ? OPJ_TRUE : OPJ_FALSE;
}

static asn1SccJpeg_Result_Code check_config(const asn1SccJpeg_Compression_Config *config,
                                            image_geometry_t *geometry)
{
   int error_code = 0;

   if (!asn1SccJpeg_Compression_Config_IsConstraintValid(config, &error_code)) {
      return Jpeg_Result_Code_invalid_config;
   }

   geometry->width = (OPJ_UINT32)config->width;
   geometry->height = (OPJ_UINT32)config->height;
   geometry->num_components = (OPJ_UINT32)config->num_components;
   geometry->bytes_per_sample = (config->bit_depth <= 8U) ? 1U : 2U;
   geometry->image_size = (OPJ_SIZE_T)geometry->width * geometry->height *
                          geometry->num_components * geometry->bytes_per_sample;
   if (config->tile_size == 0U) {
      geometry->tile_width = geometry->width;
      geometry->tile_height = geometry->height;
   } else {
      geometry->tile_width = (OPJ_UINT32)config->tile_size;
      geometry->tile_height = (OPJ_UINT32)config->tile_size;
   }
   geometry->tiles_x = (geometry->width + geometry->tile_width - 1U) / geometry->tile_width;
   geometry->tiles_y = (geometry->height + geometry->tile_height - 1U) / geometry->tile_height;

   if (geometry->image_size > JPEGCOMPRESSOR_INPUT_BUFFER_SIZE) {
      return Jpeg_Result_Code_invalid_config;
   }
   // JPEG 2000 limits the number of tiles to 65535
   if (geometry->tiles_x * geometry->tiles_y > 65535U) {
      return Jpeg_Result_Code_invalid_config;
   }
   if (!tile_supports_resolutions(geometry, (OPJ_UINT32)config->resolutions)) {
      return Jpeg_Result_Code_invalid_config;
   }
   if (compressor.input_size != geometry->image_size) {
      return Jpeg_Result_Code_input_size_mismatch;
   }
   return Jpeg_Result_Code_ok;
}

static void setup_parameters(const asn1SccJpeg_Compression_Config *config)
{
   opj_cparameters_t *parameters = &encoder_parameters;

   opj_set_default_encoder_parameters(parameters);
   parameters->tcp_numlayers = 1;
   parameters->cp_disto_alloc = 1;
   if (config->compression_ratio > 1U) {
      parameters->irreversible = 1;
      parameters->tcp_rates[0] = (float)config->compression_ratio;
   } else {
      parameters->irreversible = 0;
      parameters->tcp_rates[0] = 0.0f; // lossless
   }
   parameters->numresolution = (int)config->resolutions;
   if (config->tile_size != 0U) {
      parameters->tile_size_on = OPJ_TRUE;
      parameters->cp_tdx = (int)config->tile_size;
      parameters->cp_tdy = (int)config->tile_size;
   }
   // Multi-component (colour) transform on the first 3 components
   parameters->tcp_mct = (config->num_components >= 3U) ? 1 : 0;
}

// Copy the samples of one tile from INPUT_BUFFER to tile_buffer (of
// tile_buffer_size bytes), in the layout expected by opj_write_tile (planar,
// row by row), and give the number of bytes copied in tile_size.
// Returns OPJ_FALSE, without copying anything, if the tile is outside the
// image or if its data would not fit in INPUT_BUFFER or tile_buffer.
static OPJ_BOOL gather_tile(const image_geometry_t *geometry, OPJ_UINT32 tile_x, OPJ_UINT32 tile_y,
                            OPJ_UINT8 *tile_buffer, OPJ_SIZE_T tile_buffer_size, OPJ_SIZE_T *tile_size)
{
   const OPJ_UINT32 x0 = tile_x * geometry->tile_width;
   const OPJ_UINT32 y0 = tile_y * geometry->tile_height;

   *tile_size = 0U;
   if ((x0 >= geometry->width) || (y0 >= geometry->height)) {
      return OPJ_FALSE;
   }

   // Edge tiles are cut at the image border
   OPJ_UINT32 width = geometry->width - x0;
   OPJ_UINT32 height = geometry->height - y0;
   if (width > geometry->tile_width) {
      width = geometry->tile_width;
   }
   if (height > geometry->tile_height) {
      height = geometry->tile_height;
   }
   const OPJ_SIZE_T line_size = (OPJ_SIZE_T)geometry->width * geometry->bytes_per_sample;
   const OPJ_SIZE_T plane_size = line_size * geometry->height;
   const OPJ_SIZE_T row_size = (OPJ_SIZE_T)width * geometry->bytes_per_sample;
   const OPJ_SIZE_T copy_size = row_size * height * geometry->num_components;
   // End of the last row read: last row of the tile in the last component
   const OPJ_SIZE_T source_end = (OPJ_SIZE_T)(geometry->num_components - 1U) * plane_size +
                                 (OPJ_SIZE_T)(y0 + height - 1U) * line_size +
                                 (OPJ_SIZE_T)x0 * geometry->bytes_per_sample + row_size;

   if ((copy_size > tile_buffer_size) || (source_end > JPEGCOMPRESSOR_INPUT_BUFFER_SIZE)) {
      return OPJ_FALSE;
   }

   OPJ_UINT8 *destination = tile_buffer;
   for (OPJ_UINT32 component = 0U; component < geometry->num_components; component++) {
      const OPJ_UINT8 *source = INPUT_BUFFER + component * plane_size +
                                y0 * line_size + (OPJ_SIZE_T)x0 * geometry->bytes_per_sample;
      for (OPJ_UINT32 row = 0U; row < height; row++) {
         memcpy(destination, source, row_size);
         destination += row_size;
         source += line_size;
      }
   }
   *tile_size = copy_size;
   return OPJ_TRUE;
}

static OPJ_BOOL encode(const asn1SccJpeg_Compression_Config *config, const image_geometry_t *geometry)
{
   opj_image_cmptparm_t component_parameters[4] = { { 0 } };
   opj_image_t *image = NULL;
   opj_codec_t *codec = NULL;
   opj_stream_t *stream = NULL;
   OPJ_UINT8 *tile_buffer = NULL;
   const OPJ_SIZE_T tile_buffer_size = (OPJ_SIZE_T)geometry->tile_width * geometry->tile_height *
                                       geometry->num_components * geometry->bytes_per_sample;
   OPJ_BOOL single_tile = (geometry->tiles_x * geometry->tiles_y == 1U);
   OPJ_BOOL success = OPJ_FALSE;

   for (OPJ_UINT32 i = 0U; i < geometry->num_components; i++) {
      component_parameters[i].dx = 1U;
      component_parameters[i].dy = 1U;
      component_parameters[i].w = geometry->width;
      component_parameters[i].h = geometry->height;
      component_parameters[i].prec = (OPJ_UINT32)config->bit_depth;
      component_parameters[i].sgnd = config->is_signed ? 1U : 0U;
   }

   // A single tile is passed directly from INPUT_BUFFER, which already has
   // the expected layout; otherwise each tile is gathered in a pool buffer
   if (!single_tile) {
      tile_buffer = (OPJ_UINT8 *)opj_image_data_alloc(tile_buffer_size);
   }
   // Image without sample data: samples are given tile by tile
   image = opj_image_tile_create(geometry->num_components, component_parameters,
                                 (geometry->num_components == 1U) ? OPJ_CLRSPC_GRAY :
                                 (geometry->num_components == 3U) ? OPJ_CLRSPC_SRGB :
                                 OPJ_CLRSPC_UNSPECIFIED);
   codec = opj_create_compress(OPJ_CODEC_J2K);
   stream = opj_stream_create(JPEGCOMPRESSOR_STREAM_CHUNK_SIZE, OPJ_FALSE);

   // Encode only if every object above was created. They come from the
   // memory pool, so a NULL means the pool is exhausted (reported as
   // out-of-memory by compress()). The tile buffer is only needed when the
   // image has several tiles.
   const OPJ_BOOL tile_buffer_ready = single_tile || (tile_buffer != NULL);
   const OPJ_BOOL encoder_ready = tile_buffer_ready && (image != NULL) && (codec != NULL) &&
                                  (stream != NULL);

   if (encoder_ready) {
      image->x0 = 0U;
      image->y0 = 0U;
      image->x1 = geometry->width;
      image->y1 = geometry->height;
      opj_stream_set_write_function(stream, stream_write);

      success = opj_setup_encoder(codec, &encoder_parameters, image) &&
                opj_start_compress(codec, image, stream);

      if (single_tile) {
         success = success &&
                   opj_write_tile(codec, 0U, INPUT_BUFFER, (OPJ_UINT32)geometry->image_size, stream);
      } else {
         for (OPJ_UINT32 tile_y = 0U; success && (tile_y < geometry->tiles_y); tile_y++) {
            for (OPJ_UINT32 tile_x = 0U; success && (tile_x < geometry->tiles_x); tile_x++) {
               OPJ_SIZE_T tile_size = 0U;

               success = gather_tile(geometry, tile_x, tile_y, tile_buffer, tile_buffer_size, &tile_size) &&
                         opj_write_tile(codec, tile_y * geometry->tiles_x + tile_x,
                                        tile_buffer, (OPJ_UINT32)tile_size, stream);
            }
         }
      }
      success = success && opj_end_compress(codec, stream);
   }

   if (stream != NULL) {
      opj_stream_destroy(stream);
   }
   if (codec != NULL) {
      opj_destroy_codec(codec);
   }
   if (image != NULL) {
      opj_image_destroy(image);
   }
   opj_image_data_free(tile_buffer);
   return success;
}

static void release_encoder_memory(void)
{
   compressor.memory_peak = opj_mem_pool_get_peak();
   compressor.memory_leaked = opj_mem_pool_get_used();
   compressor.memory_high_water = opj_mem_pool_get_high_water();
   opj_mem_pool_init(opj_pool_buffer, sizeof(opj_pool_buffer));
}

// Pool bytes OpenJPEG had not freed at the end of the last compression
// (expected 0; released by the pool reset anyway).
OPJ_SIZE_T jpegcompressor_get_memory_leaked(void)
{
   return compressor.memory_leaked;
}

// Highest pool offset used by the last compression: the pool size it really
// needed, including the memory lost to fragmentation (compare with the status
// memory-peak). Not a TASTE interface: used by the Linux test (test_env).
OPJ_SIZE_T jpegcompressor_get_memory_high_water(void)
{
   return compressor.memory_high_water;
}

static asn1SccJpeg_Result_Code compress(const asn1SccJpeg_Compression_Config *config)
{
   image_geometry_t geometry = { 0 };

   compressor.output_size = 0U;
   compressor.output_overflow = OPJ_FALSE;

   asn1SccJpeg_Result_Code result = check_config(config, &geometry);
   if (result == Jpeg_Result_Code_ok) {
      setup_parameters(config);
      if (!encode(config, &geometry)) {
         compressor.output_size = 0U;
         if (compressor.output_overflow) {
            result = Jpeg_Result_Code_output_overflow;
         } else if (opj_mem_pool_get_failures() > 0U) {
            result = Jpeg_Result_Code_out_of_memory;
         } else {
            result = Jpeg_Result_Code_codec_error;
         }
      }
   }

   // Single exit: the pool is emptied after every compression
   release_encoder_memory();
   return result;
}


